func Cairkan(ctx context.Context, db *sql.DB, dir string) error {
    f, _ := os.OpenFile(dir+"/pencairan.csv", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
    for _, w := range warungBersaldo(ctx, db) {
        tx, _ := db.BeginTx(ctx, nil)
        catatJurnalPencairan(ctx, tx, w)
        fmt.Fprintf(f, "%d,%s,%d\n", w.Akun, w.Nama, w.Saldo)
        tx.Commit()
    }
    return nil
}

